use App\Filament\Resources\ReturnRequests\Pages\{EditReturnRequest,ListReturnRequests};use App\Models\ReturnRequest;use Filament\Resources\Resource;use Filament\Schemas\Schema;use Filament\Tables\Table;use Filament\Forms\Components\{Repeater,Select,TextInput,Textarea};use Filament\Tables\Columns\TextColumn;
class ReturnRequestResource extends Resource{protected static ?string $model=ReturnRequest::class;protected static ?string $navigationLabel='Devoluções';protected static string|\UnitEnum|null $navigationGroup='Loja online';public static function form(Schema $s):Schema{return $s->components([TextInput::make('reference')->disabled(),Select::make('status')->options(['requested'=>'Pedido recebido','approved'=>'Aprovado','rejected'=>'Recusado','received'=>'Artigos recebidos','refunded'=>'Reembolsado','closed'=>'Fechado'])->required(),TextInput::make('reason')->disabled(),Textarea::make('details')->disabled()->columnSpanFull(),TextInput::make('requested_amount')->prefix('€'),TextInput::make('refunded_amount')->prefix('€'),TextInput::make('stripe_refund_id')->label('ID do reembolso Stripe')->disabled(),Repeater::make('items')->relationship()->schema([TextInput::make('order_item_id')->disabled(),TextInput::make('quantity')->disabled(),TextInput::make('condition')])->columns(3)->columnSpanFull(),Textarea::make('internal_notes')->columnSpanFull()]);}public static function table(Table $t):Table{return $t->columns([TextColumn::make('created_at')->dateTime('d/m/Y H:i')->sortable(),TextColumn::make('reference')->searchable(),TextColumn::make('order.number')->label('Encomenda'),TextColumn::make('reason'),TextColumn::make('status')->badge(),TextColumn::make('refunded_amount')->money('EUR')])->recordActions([\Filament\Actions\EditAction::make()]);}public static function getPages():array{return ['index'=>ListReturnRequests::route('/'),'edit'=>EditReturnRequest::route('/{record}/edit')];}}
